"""Export the trained frame model to Kotlin for the Android app.

The exported detector mirrors the Python pipeline: same framing, same 25 ms window and
10 ms hop, same pooled 0.25 s grid, same rolling baselines. Only the numbers differ.
"""

from __future__ import annotations

import argparse
from pathlib import Path

from common import DATA, read_json

TEMPLATE = '''package au.com.shiftyjelly.pocketcasts.repositories.ads

/**
 * GENERATED by dev/adaware/scripts/06_export_kotlin.py - do not edit.
 *
 * Podcast ad detector: logistic regression over 0.25 s audio frames.
 * Trained on {n_episodes} episodes; leave-one-episode-out interval P {precision:.2f} / R {recall:.2f}
 * at {tolerance:.0f} s boundary tolerance (dev/adaware/README.md).
 */
object AdDetectorModel {{
    const val GRID_SECONDS = {grid:.2f}f
    const val THRESHOLD = {threshold:.3f}f
    const val SMOOTH_SECONDS = {smooth:.1f}f
    const val MIN_AD_SECONDS = {min_duration:.1f}f
    const val MERGE_GAP_SECONDS = {merge_gap:.1f}f

    // 25 ms window, 10 ms hop, 16 kHz mono
    const val SAMPLE_RATE = 16000
    const val FRAME_SIZE = 400
    const val HOP_SIZE = 160
    const val FFT_SIZE = 512

    val mean = floatArrayOf({mean})
    val scale = floatArrayOf({scale})
    val weights = floatArrayOf({weights})
    const val BIAS = {bias:.6f}f

    /** Feature order, for debugging and for keeping the Kotlin extractor in sync. */
    val featureNames = arrayOf(
{names}
    )

    fun score(features: FloatArray): Float {{
        var z = BIAS
        for (i in features.indices) {{
            z += weights[i] * ((features[i] - mean[i]) / scale[i])
        }}
        return 1f / (1f + kotlin.math.exp(-z))
    }}
}}
'''


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--model", default="model.json")
    ap.add_argument("--metrics", default="metrics.json")
    ap.add_argument("--out", default="out/AdDetector.kt")
    args = ap.parse_args()

    model = read_json(DATA / "model" / args.model)
    metrics = read_json(DATA / "model" / args.metrics, default={})

    def fmt(vals, per_line=6, fmt="{:.6f}"):
        chunks = []
        for i in range(0, len(vals), per_line):
            chunks.append(", ".join(fmt.format(v) for v in vals[i : i + per_line]))
        return (",\n            ").join(chunks)

    names = ",\n            ".join(f'"{n}"' for n in model["features"])
    code = TEMPLATE.format(
        n_episodes=len(model["train_episodes"]),
        precision=metrics.get("precision", 0.0),
        recall=metrics.get("recall", 0.0),
        tolerance=model.get("tolerance", 5.0),
        grid=model["grid_seconds"],
        threshold=model["threshold"],
        smooth=model["smooth_seconds"],
        min_duration=model["min_duration"],
        merge_gap=model["merge_gap"],
        mean=fmt(model["mean"]),
        scale=fmt([max(1e-6, s) for s in model["scale"]]),
        weights=fmt(model["weights"]),
        bias=model["bias"],
        names=names,
    )
    out = Path(__file__).resolve().parents[1] / args.out
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(code, encoding="utf-8")
    print(f"wrote {out} ({len(model['features'])} features)")


if __name__ == "__main__":
    main()
